const uuid = () =>
  'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = Math.floor(Math.random() * 16);
    return (c === 'x' ? r : ((r & 3) | 8)).toString(16);
  });

const correlationId = uuid();
const configuredBatchSize = Number($env.SIS_NOTIFICATION_BATCH_SIZE || 20);
const batchSize = Number.isFinite(configuredBatchSize)
  ? Math.max(1, Math.min(100, configuredBatchSize))
  : 20;

return [
  {
    json: {
      correlationId,
      workerId: `n8n:08-notification-dispatcher:${$execution.id}`,
      batchSize,
      request: {
        operation: 'notification.claim',
        correlation_id: correlationId,
        submitted_at: new Date().toISOString(),
        source: { channel: 'n8n_schedule' },
        payload: {
          worker_id: `n8n:08-notification-dispatcher:${$execution.id}`,
          limit: batchSize,
        },
      },
    },
  },
];

