const inputItems = $input.all();
if (inputItems.length !== 1) {
  throw new Error('NOTIFICATION_CLAIM_ITEM_COUNT_INVALID');
}

const raw = inputItems[0].json ?? {};
let body = Object.prototype.hasOwnProperty.call(raw, 'body')
  ? raw.body
  : raw;

if (typeof body === 'string') {
  try {
    body = JSON.parse(body);
  } catch {
    throw new Error('NOTIFICATION_CLAIM_INVALID_RESPONSE');
  }
}

if (Array.isArray(body) && body.length === 1 && body[0]) {
  body = body[0];
}

if (!body || typeof body !== 'object' || body.success !== true) {
  const code =
    body?.error?.code ||
    body?.code ||
    raw.error?.message ||
    raw.message ||
    'NOTIFICATION_CLAIM_FAILED';
  throw new Error(String(code));
}

const notifications = Array.isArray(body?.data?.notifications)
  ? body.data.notifications
  : [];

if (notifications.length === 0) {
  return [
    {
      json: {
        hasNotification: false,
        claimedCount: 0,
        claimResult: body,
      },
      pairedItem: { item: 0 },
    },
  ];
}

const renderMessage = (notification) => {
  const payload = notification.payload || {};
  const name = notification.recipient_name
    ? ` ${notification.recipient_name}`
    : '';

  const templates = {
    'student-profile-ack':
      `Dear${name},\n\n` +
      `Your student profile has been received. Student number: ` +
      `${payload.student_number || 'pending assignment'}. ` +
      `Required documents may still need staff verification.\n\n` +
      `Regards,\nAcademic Administration`,

    'enrollment-decision':
      `Dear${name},\n\n` +
      `Your enrollment request has been processed. Current outcome: ` +
      `${String(payload.overall_outcome || 'review pending').replaceAll('_', ' ')}.` +
      `\n\nRegards,\nAcademic Administration`,
  };

  return (
    templates[notification.template_code] ||
    `Dear${name},\n\n` +
      `There is an update regarding ` +
      `${String(notification.notification_type || 'your academic record').replaceAll('.', ' ')}. ` +
      `Please contact academic administration if further information is required.` +
      `\n\nRegards,\nAcademic Administration`
  );
};

return notifications.map((notification) => ({
  json: {
    hasNotification: true,
    notification,
    renderedSubject:
      notification.subject || 'Academic administration update',
    renderedMessage: renderMessage(notification),
  },
  pairedItem: { item: 0 },
}));

const source = $('Render Notification Batch').item.json;
const raw = $json ?? {};

let body = Object.prototype.hasOwnProperty.call(raw, 'body')
  ? raw.body
  : raw;

if (typeof body === 'string') {
  try {
    body = JSON.parse(body);
  } catch {
    throw new Error('NOTIFICATION_BEGIN_INVALID_RESPONSE');
  }
}

if (Array.isArray(body) && body.length === 1 && body[0]) {
  body = body[0];
}

if (!body || typeof body !== 'object' || body.success !== true) {
  const code =
    body?.error?.code ||
    body?.code ||
    raw.error?.message ||
    raw.message ||
    'NOTIFICATION_BEGIN_FAILED';
  throw new Error(String(code));
}

return {
  json: {
    ...source,
    shouldSend: body.data?.should_send === true,
    beginResult: body,
  },
};

const source = $('Begin Attempt Decision').item.json;
const notification = source.notification;
const raw = $json ?? {};

const errorText = String(
  raw.error?.message ||
  raw.message ||
  raw.description ||
  ''
);

const providerMessageId =
  raw.id ||
  raw.messageId ||
  raw.threadId ||
  '';

const delivered = Boolean(providerMessageId) && !errorText;

const uncertainOutcome =
  !delivered &&
  /(timeout|timed out|network|econn|socket|connection reset|connection closed|no response)/i
    .test(errorText);

const explicitTemporaryFailure =
  !delivered &&
  !uncertainOutcome &&
  /(429|rate limit|quota|temporar|unavailable|5\d\d|backend error)/i
    .test(errorText);

let deliveryStatus;
let retryable;
let errorCode;

if (delivered) {
  deliveryStatus = 'delivered';
  retryable = false;
  errorCode = '';
} else if (uncertainOutcome) {
  deliveryStatus = 'dead_letter';
  retryable = false;
  errorCode = 'NOTIFICATION_DELIVERY_OUTCOME_UNKNOWN';
} else if (explicitTemporaryFailure) {
  deliveryStatus = 'temporary_failure';
  retryable = true;
  errorCode = 'NOTIFICATION_TEMPORARY_FAILURE';
} else {
  deliveryStatus = 'permanent_failure';
  retryable = false;
  errorCode = 'NOTIFICATION_PROVIDER_REJECTED';
}

return {
  json: {
    request: {
      operation: 'notification.delivery.record',
      correlation_id: notification.correlation_id,
      idempotency_key:
        `notification:${notification.outbox_id}:attempt:` +
        `${notification.attempt_number}`,
      submitted_at: new Date().toISOString(),
      source: {
        channel: 'n8n',
        workflow_code: '08-notification-dispatcher',
      },
      payload: {
        outbox_id: notification.outbox_id,
        attempt_number: notification.attempt_number,
        delivery_status: deliveryStatus,
        provider: 'gmail',
        provider_message_id: providerMessageId || null,
        error_code: errorCode || null,
        error_message:
          delivered
            ? null
            : (errorText || 'Gmail did not return a message identifier.').slice(0, 300),
        retryable,
      },
    },
    deliveryStatus,
    outboxId: notification.outbox_id,
    providerMessageId: providerMessageId || null,
  },
};

const notification = $json.notification;

return {
  json: {
    request: {
      operation: 'notification.delivery.record',
      correlation_id: notification.correlation_id,
      idempotency_key:
        `notification:${notification.outbox_id}:attempt:` +
        `${notification.attempt_number}`,
      submitted_at: new Date().toISOString(),
      source: {
        channel: 'n8n',
        workflow_code: '08-notification-dispatcher',
      },
      payload: {
        outbox_id: notification.outbox_id,
        attempt_number: notification.attempt_number,
        delivery_status: 'permanent_failure',
        provider: notification.channel,
        provider_message_id: null,
        error_code: 'NOTIFICATION_CHANNEL_NOT_CONFIGURED',
        error_message:
          'The requested notification channel is not configured in this pilot.',
        retryable: false,
      },
    },
    deliveryStatus: 'permanent_failure',
    outboxId: notification.outbox_id,
  },
};

const source =
  $('Build Gmail Attempt Result').isExecuted
    ? $('Build Gmail Attempt Result').item.json
    : $('Build Unsupported Channel Result').item.json;

const raw = $json ?? {};
let body = Object.prototype.hasOwnProperty.call(raw, 'body')
  ? raw.body
  : raw;

if (typeof body === 'string') {
  try {
    body = JSON.parse(body);
  } catch {
    throw new Error('NOTIFICATION_RECORD_INVALID_RESPONSE');
  }
}

if (Array.isArray(body) && body.length === 1 && body[0]) {
  body = body[0];
}

if (!body || typeof body !== 'object' || body.success !== true) {
  const code =
    body?.error?.code ||
    body?.code ||
    raw.error?.message ||
    raw.message ||
    'NOTIFICATION_RECORD_FAILED';
  throw new Error(String(code));
}

return {
  json: {
    ...source,
    recordResult: body,
    recordSuccess: true,
  },
};
